// Batch Input: the caller's passthrough item, one per call, exactly as the parent shaped it.
// Two modes, one machine (ruled 2026-09-02). Mode "writer": one 250-company batch through
// ContaGen and Supersoniq, Clean Fields, DNC, the People writer, the Companies stamps, a recount,
// its own Hub row keyed "<parentExecId>-<batchNum>", and the recount's held state back to the
// parent. Mode "ark": ONE pass for the whole run, fired by the parent, not awaited, once the
// writer lane has drained (rebuilt 2026-09-02; before that it was one pass per batch and the
// overlapping passes 429'd each other off AI-Ark's global ceiling). It carries every company from
// every closed writer batch with that batch's recount as held state, one AI-Ark export per company
// still under its band cap, completion through the callback door's data table, the People writer,
// no new stamps, its own Hub row keyed "<parentExecId>-ark" (the parent waits on that row).
// The key parts are required here, before any paid call; startedAt is the clock Duration s runs on.
const raw=$input.first().json||{};
const inp=Object.assign({}, raw);
const mode=String(inp.mode||'writer').toLowerCase()==='ark'?'ark':'writer';
const parentExecId=String(inp.parentExecId||'').trim();
const batchNum=Math.floor(Number(inp.batchNum)||0);
const who='Waterfall Contacts Batch ('+mode+')';
if(!parentExecId) throw new Error(who+' was called without parentExecId. Its Hub row is keyed by it. Nothing was pulled.');
if(mode==='writer'&&!(batchNum>0)) throw new Error(who+' '+parentExecId+' was called without batchNum. Its Hub row is keyed "<parentExecId>-<batchNum>". Nothing was pulled.');
if(!/^app[A-Za-z0-9]{14}$/.test(String(inp.base||''))) throw new Error(who+' '+parentExecId+' has no valid base. Nothing was pulled.');
for(const k of ['peopleTableId','companiesTableId']){ if(!inp[k]) throw new Error(who+' '+parentExecId+' has no '+k+'. Nothing was pulled.'); }
if(!Array.isArray(inp.companies)||!inp.companies.length) throw new Error(who+' '+parentExecId+' received an empty company list. The parent must never send one.');
inp.mode=mode;
inp.parentExecId=parentExecId;
inp.batchNum=batchNum;
inp.logKey=mode==='ark'?(parentExecId+'-ark'):(parentExecId+'-'+String(batchNum));
inp.startedAt=new Date().toISOString();
return [{ json: inp }];

// Plan Batch: the companies in, the plan out. People per company follows size, a rule in code
// (ruled 2026-09-02): 1-10 employees 4, 11-50 6, 51-200 10, 201 and up 12, unknown 6. The cap is
// a per-source cap at ContaGen and Supersoniq (every company in the batch, grouped by band so
// results_by_company and per_company_limit are the band cap) and absolute at AI-Ark (gap-sized,
// planned by the ark pass after one recount over the whole run). In mode "writer" the tier-1 and
// tier-2 requests are built here; in mode "ark" only the band caps are needed and no request is
// built. Pull WIDE, cut in the base: the nets here are fixed; who gets messaged is the relevance
// formula and the views on People. No Tag: People stores none (a lookup through Companies).
//
// TWO LEVERS ON THE LAUNCH ROW (ruled 2026-09-02), both carried here by the parent:
//   arkOnly, set when Tiers is the "AI-Ark" mode: a FLAT cap of five people per company, every
//   company size, instead of the band caps. Nothing else about the bands changes.
//   cgSeniority / sqSeniority, the launch row's Roles mapped into each provider's vocabulary by
//   the parent's Launch Params: present, they REPLACE the in-code seniority net for that provider
//   (including the 1-10 widening); absent, the in-code nets below stand unchanged.
const inp=$input.first().json||{};
const companies=Array.isArray(inp.companies)?inp.companies:[];
if(!companies.length) throw new Error('Waterfall Contacts Batch received an empty company list. The parent must never send one.');
const mode=inp.mode==='ark'?'ark':'writer';
const sources=Array.isArray(inp.sources)?inp.sources:[];
const on=(s)=>sources.indexOf(s)>-1;
const arkOnly=inp.arkOnly===true;
const ARK_ONLY_CAP=5;
const BANDS=['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'];
const band=(v)=>{ const s=String(v==null?'':v).trim(); if(!s) return ''; if(BANDS.indexOf(s)>-1) return s; const n=Number(s.replace(/[,\s]/g,'')); if(!isFinite(n)||n<=0) return ''; if(n<=10) return '1-10'; if(n<=50) return '11-50'; if(n<=200) return '51-200'; if(n<=500) return '201-500'; if(n<=1000) return '501-1000'; if(n<=5000) return '1001-5000'; if(n<=10000) return '5001-10000'; return '10001+'; };
const capOf=(b)=>{ if(arkOnly) return ARK_ONLY_CAP; if(b==='1-10') return 4; if(b==='11-50') return 6; if(b==='51-200') return 10; if(b) return 12; return 6; };
const plan=companies.map(c=>{ const b=band(c.employees); return {
  recordId:c.recordId, domain:String(c.domain||'').trim().toLowerCase(), company:String(c.company||'').trim(),
  band:b||'unknown', small:b==='1-10', cap:capOf(b),
  held:Number(c.heldCount)||0,
  heldKeys:(Array.isArray(c.heldKeys)?c.heldKeys:[]).map(k=>String(k).toLowerCase()),
  heldLinkedin:(Array.isArray(c.heldLinkedin)?c.heldLinkedin:[]).map(l=>String(l).trim()).filter(Boolean)
}; }).filter(c=>c.domain);
// One group per (net, cap): 1-10 is the wider net at cap 4; an unknown band shares cap 6 with 11-50.
const groups={};
for(const c of plan){ const k=(c.small?'small':'standard')+':'+String(c.cap).padStart(2,'0'); (groups[k]=groups[k]||{ small:c.small, cap:c.cap, list:[] }).list.push(c); }
const chunk=(arr,n)=>{ const out=[]; for(let i=0;i<arr.length;i+=n) out.push(arr.slice(i,i+n)); return out; };
// Tier 1, ContaGen (DiscoLike contacts/discover, domain mode): seniority executive, vp, director,
// manager, plus senior_ic for 1-10; department only when the launch row mapped one; 250 domains per call.
const CG_SEN=['executive','vp','director','manager'];
const cgDep=Array.isArray(inp.cgDepartments)?inp.cgDepartments:[];
const cgRoles=Array.isArray(inp.cgSeniority)?inp.cgSeniority:[];
const sqRoles=Array.isArray(inp.sqSeniority)?inp.sqSeniority:[];
// Tier 2, Supersoniq companies/enrich: their vocabulary exactly as SQ Contacts Batch sends it
// (Unclassified included: "we don't know" is not "not a decision-maker"), Senior added for 1-10,
// no department, no country, tier full so the email rides, up to 1,000 domains per call.
const STANDARD_SEN=['Manager','Senior Manager','Director','Head','VP','EVP / SVP','President','C-Suite','Owner','Founder','Partner','Board / Chair','Unclassified'];
const SMALL_SEN=STANDARD_SEN.concat(['Senior']);
const cgRequests=[], sqRequests=[];
if(mode==='writer'){
  for(const k of Object.keys(groups).sort()){
    const g=groups[k];
    if(on('ContaGen')){
      for(const part of chunk(g.list,250)){
        const body={ domain:part.map(c=>c.domain), seniority:(cgRoles.length?cgRoles:(g.small?CG_SEN.concat(['senior_ic']):CG_SEN)), max_companies:part.length, results_by_company:g.cap };
        if(cgDep.length) body.department=cgDep;
        cgRequests.push({ body:body, domains:part.map(c=>c.domain), cap:g.cap });
      }
    }
    if(on('Supersoniq')){
      for(const part of chunk(g.list,1000)){
        sqRequests.push({ body:{ companies:part.map(c=>({ domain:c.domain })), filters:{ seniority:(sqRoles.length?sqRoles:(g.small?SMALL_SEN:STANDARD_SEN)) }, per_company_limit:g.cap, tier:'full' }, domains:part.map(c=>c.domain), cap:g.cap });
      }
    }
  }
}
return [{ json: {
  mode:mode, batchNum:Number(inp.batchNum)||0, batchCount:Number(inp.batchCount)||0,
  sources:sources, plan:plan, cgRequests:cgRequests, sqRequests:sqRequests,
  arkOnly:arkOnly, capRule:(arkOnly?('flat '+ARK_ONLY_CAP):'by band'),
  arkOn:mode==='ark'&&on('AI-Ark'), arkFunctions:(Array.isArray(inp.arkFunctions)?inp.arkFunctions:[]),
  arkSeniority:(Array.isArray(inp.arkSeniority)?inp.arkSeniority:[])
} }];

// Plan Ready: the DNC read sits between Plan Batch and the tiers so both DNC passes share it;
// re-emit the plan as the one item the gates read, so no gate ever evaluates against DNC rows.
return [{ json: $('Plan Batch').first().json }];

// Parse ContaGen: DiscoLike /contacts/discover responses (fullResponse items aligned to CG
// Requests) -> people per domain, truncated to the band cap. An errored call (after the node's
// own retries) counts once and lands in the counters with its reason; nothing is silently dropped.
const plan=$('Plan Batch').first().json;
const byDomain={}; for(const c of plan.plan) byDomain[c.domain]=c;
let reqs=[]; try{ reqs=$('CG Requests').all().map(i=>i.json); }catch(e){}
let items=[]; try{ items=$('ContaGen Discover').all(); }catch(e){}
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const why=(b,raw)=>{ const m=b&&typeof b==='object'?(b.detail||b.error||b.message):null; const s=m?String(typeof m==='object'?JSON.stringify(m):m):(typeof raw==='string'?raw:(raw?JSON.stringify(raw):'')); return String(s||'empty body').slice(0,200); };
const linkedinOf=(urls)=>Array.isArray(urls)?(urls.find(u=>/linkedin\.com\/in\//i.test(String(u)))||''):'';
const firstPhone=(p)=>Array.isArray(p)&&p.length?String((p[0]&&p[0].phone)||p[0]||''):(p?String(p):'');
const people={}; const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[] };
items.forEach((it,i)=>{
  const req=reqs[i]; if(!req) return;
  st.called++;
  const j=it.json||{};
  if(j.error&&j.statusCode===undefined){ st.errors++; const r='ContaGen: '+String((j.error&&(j.error.message||j.error.description))||'call failed').slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const status=Number(j.statusCode)||0; const b=parse(j.body===undefined?j:j.body);
  if(!(status>=200&&status<300)||!b||typeof b!=='object'){ st.errors++; const r='ContaGen HTTP '+status+' '+why(b,j.body); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const cr=b.credits_used!=null?b.credits_used:(b.credits!=null?b.credits:((b.usage&&b.usage.credits_used)||0)); st.credits+=Number(cr)||0;
  const results=(b.results&&typeof b.results==='object')?b.results:{};
  for(const d of req.domains){
    const entry=results[d]||null; const c=byDomain[d]; if(!entry||!c) continue;
    const contacts=Array.isArray(entry.contacts)?entry.contacts:[];
    st.returned+=contacts.length;
    const list=people[d]||(people[d]=[]);
    for(const p of contacts){
      if(list.length>=c.cap) break;
      list.push({ source:'ContaGen', sourceId:String(p.persona_id||''), name:String(p.name||'').trim(), title:String(p.title||'').trim(), seniority:String(p.seniority||''), department:String(p.department||''), email:String(p.email||'').trim(), linkedin:linkedinOf(p.social_urls), phone:firstPhone(p.phone), state:String(p.state||'') });
      st.kept++;
    }
  }
});
return [{ json: { people: people, stats: st } }];

// Parse Supersoniq: companies/enrich responses -> people per domain (Format Batch's parse).
// Contacts at domains we did not send are dropped; an email whose domain is neither the
// company domain nor a subdomain of it is blanked, the person kept. Their LinkedIn URLs
// never route to LinkedIn (the name-match fence lives on the table). Never throws on a
// failed response: the failure rides in the counters and the parent decides.
const plan=$('Plan Batch').first().json;
const byDomain={}; for(const c of plan.plan) byDomain[c.domain]=c;
let reqs=[]; try{ reqs=$('SQ Requests').all().map(i=>i.json); }catch(e){}
let items=[]; try{ items=$('SQ Enrich').all(); }catch(e){}
const people={}; const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], dropped:0, emailBlanked:0 };
const emailDomainOk=(email,domain)=>{ const at=String(email||'').lastIndexOf('@'); if(at<0) return false; const ed=String(email).slice(at+1).toLowerCase().trim(); return ed===domain||ed.endsWith('.'+domain); };
items.forEach((it,i)=>{
  const req=reqs[i]; if(!req) return;
  st.called++;
  const resp=it.json||{};
  if(!Array.isArray(resp.results)){ st.errors++; const r='Supersoniq: '+JSON.stringify(resp).slice(0,200); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const cr=resp.credits_used!=null?resp.credits_used:(resp.credits!=null?resp.credits:((resp.usage&&resp.usage.credits_used)||0)); st.credits+=Number(cr)||0;
  const sent=new Set(req.domains);
  for(const r of resp.results){
    const contacts=Array.isArray(r.contacts)?r.contacts:[];
    for(const ct of contacts){
      st.returned++;
      const domain=String(ct.company_domain||'').trim().toLowerCase();
      const c=byDomain[domain];
      if(!domain||!sent.has(domain)||!c){ st.dropped++; continue; }
      const list=people[domain]||(people[domain]=[]);
      if(list.length>=c.cap) continue;
      const full=((String(ct.first_name||'')+' '+String(ct.last_name||'')).trim())||String(ct.full_name||'');
      let email=String(ct.email||'').trim();
      if(email&&!emailDomainOk(email,domain)){ email=''; st.emailBlanked++; }
      list.push({ source:'Supersoniq', sourceId:String(ct.contact_id||ct.id||''), name:full, title:String(ct.job_title||'').trim(), seniority:String(ct.seniority||''), department:String(ct.function||''), email:email, linkedin:String(ct.linkedin_url||ct.linkedin||'').trim(), phone:'', state:'' });
      st.kept++;
    }
  }
});
return [{ json: { people: people, stats: st } }];

// Build People: every person ContaGen and Supersoniq returned, in that order, into the
// register's People shape. The fill-blanks rule: a person the base already holds (Contact Key
// or LinkedIn URL, tier zero) is never written at all, and a later tier never overwrites an
// earlier one. The cap is per source here (each tier already returned at most the band cap),
// absolute only at AI-Ark. People stores no Domain, Company or Tag (lookups through the Companies
// link, ruled 2026-09-02): the row carries the link and the Contact Key built from the company's
// domain, and the domain itself rides on the _domain carrier for the DNC pass and the coverage
// count, stripped before the write. Names go out raw; Clean Fields splits them into first_name /
// last_name next. The Seniority and Department vocabularies come from the field register, inlined
// by the push as REGISTER at the @@register line; the maps below translate each source into them.
const REGISTER = {"tables":[{"name":"Companies","primary":"Domain","fields":[{"name":"Domain","kind":"plain","type":"singleLineText","company":true},{"name":"Company","kind":"plain","type":"singleLineText","company":true},{"name":"Description","kind":"plain","type":"multilineText","company":true},{"name":"Industry Groups","kind":"plain","type":"singleLineText","company":true},{"name":"Business Model","kind":"plain","type":"singleLineText","company":true},{"name":"Employees","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"1-10","color":"blueLight2"},{"name":"11-50","color":"cyanLight2"},{"name":"51-200","color":"tealLight2"},{"name":"201-500","color":"greenLight2"},{"name":"501-1000","color":"yellowLight2"},{"name":"1001-5000","color":"orangeLight2"},{"name":"5001-10000","color":"redLight2"},{"name":"10001+","color":"purpleLight2"}]},"company":true},{"name":"Revenue Range","kind":"plain","type":"singleLineText","company":true},{"name":"Keywords","kind":"plain","type":"singleLineText","company":true},{"name":"Country","kind":"plain","type":"singleLineText","company":true},{"name":"State","kind":"plain","type":"singleLineText","company":true},{"name":"City","kind":"plain","type":"singleLineText","company":true},{"name":"Street","kind":"plain","type":"singleLineText","company":true},{"name":"Zip","kind":"plain","type":"singleLineText","company":true},{"name":"Phones","kind":"plain","type":"singleLineText","company":true},{"name":"Public Emails","kind":"plain","type":"singleLineText","company":true},{"name":"Social URLs","kind":"plain","type":"singleLineText","company":true},{"name":"public_emails_clean","kind":"plain","type":"singleLineText","company":true},{"name":"MX Provider","kind":"plain","type":"singleLineText","company":true},{"name":"Redirect Domain","kind":"plain","type":"singleLineText","company":true},{"name":"Domain Source","kind":"plain","type":"singleLineText","company":true},{"name":"Tag","kind":"plain","type":"singleLineText","company":true},{"name":"Build Date","kind":"formula","formula":"CREATED_TIME()","refs":[]},{"name":"Contacts Pulled At","kind":"plain","type":"dateTime","options":{"dateFormat":{"name":"iso"},"timeFormat":{"name":"24hour"},"timeZone":"utc"}},{"name":"Contacts Count","kind":"count","via":"People"},{"name":"Contact Sources","kind":"rollup","via":"People","field":"Contact Source","formula":"ARRAYUNIQUE(values)"},{"name":"Signals","kind":"mirrorLink","mirror":"Signals","company":true},{"name":"Signal At","kind":"plain","type":"dateTime","options":{"dateFormat":{"name":"iso"},"timeFormat":{"name":"24hour"},"timeZone":"utc"},"company":true},{"name":"ICP Reason","kind":"plain","type":"multilineText","company":true},{"name":"Email","kind":"plain","type":"singleLineText"},{"name":"MV P0","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"ok","color":"greenBright"},{"name":"catch_all","color":"yellowBright"},{"name":"invalid","color":"redBright"},{"name":"disposable","color":"orangeLight2"},{"name":"unknown","color":"grayBright"},{"name":"error","color":"orangeBright"},{"name":"skipped","color":"grayLight2"}]}},{"name":"BB","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"verifying","color":"blueBright"},{"name":"deliverable","color":"greenBright"},{"name":"undeliverable","color":"redBright"},{"name":"risky","color":"yellowBright"},{"name":"unknown","color":"grayBright"},{"name":"error","color":"orangeBright"},{"name":"skipped","color":"grayLight2"}]}},{"name":"Final Email","kind":"plain","type":"singleLineText"},{"name":"Status","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"done","color":"greenBright"},{"name":"verifying","color":"blueBright"},{"name":"no_email_found","color":"redBright"},{"name":"error","color":"orangeBright"}]}},{"name":"Campaigns","kind":"mirrorLink","mirror":"Campaigns"},{"name":"Messages Sent","kind":"plain","type":"number","options":{"precision":0}},{"name":"Last Contacted","kind":"plain","type":"dateTime","options":{"dateFormat":{"name":"iso"},"timeFormat":{"name":"24hour"},"timeZone":"utc"}},{"name":"Campaign Status","kind":"plain","type":"singleSelect","options":{"choices":[{"name":"NEVER_CONTACTED","color":"grayLight2"},{"name":"IN_SEQUENCE","color":"blueBright"},{"name":"COMPLETED","color":"greenBright"},{"name":"REPLIED","color":"purpleBright"},{"name":"BOUNCED","color":"redBright"},{"name":"UNSUBSCRIBED","color":"orangeBright"}]}},{"name":"Bounce Reason","kind":"plain","type":"singleLineText"},{"name":"Synced At","kind":"plain","type":"dateTime","options":{"dateFormat":{"name":"iso"},"timeFormat":{"name":"24hour"},"timeZone":"utc"}},{"name":"Deploy Error","kind":"plain","type":"singleLineText"},{"name":"manually_approved","kind":"plain","type":"checkbox","options":{"color":"greenBright","icon":"check"}},{"name":"relevance","kind":"formula","formula":"IF(OR({manually_approved}, {public_emails_clean} != \"\"), 1, 0)","refs":["manually_approved","public_emails_clean"]}],"views":[{"name":"Not Sourced","filter":{"words":"Contacts Pulled At is empty","formula":"NOT({Contacts Pulled At})"},"fields":["Domain","Company","Description","Employees","Tag","Contacts Count","Contact Sources","Contacts Pulled At","Build Date"],"sort":{"field":"Build Date","direction":"desc"}},{"name":"Not Covered","filter":{"words":"Contacts Pulled At is set and Contacts Count = 0","formula":"AND({Contacts Pulled At}, {Contacts Count} = 0)"},"fields":["Domain","Company","Description","Employees","Tag","Contacts Count","Contact Sources","Contacts Pulled At","Build Date"],"sort":{"field":"Build Date","direction":"desc"}},{"name":"Covered","filter":{"words":"Contacts Count > 0","formula":"{Contacts Count} > 0"},"fields":["Domain","Company","Description","Employees","Tag","Contacts Count","Contact Sources","Contacts Pulled At","Build Date"],"sort":{"field":"Build Date","direction":"desc"}},{"name":"Cut Review","filter":{"words":"relevance = 0","formula":"{relevance} = 0"},"fields":["Domain","