const DEP={ 'executive':'Executive', 'engineering':'Engineering', 'technology':'Technology', 'it':'Technology', 'information technology':'Technology', 'r&d':'R&D', 'research & development':'R&D', 'research and development':'R&D', 'research':'R&D', 'product':'Product', 'product management':'Product', 'data':'Data', 'data science':'Data', 'analytics':'Data', 'security':'Security', 'information security':'Security', 'design':'Design', 'operations':'Operations', 'sales':'Sales', 'sales - marketing':'Sales', 'business development':'Sales', 'marketing':'Marketing', 'finance':'Finance', 'accounting':'Finance', 'human resources':'Human Resources', 'hr':'Human Resources', 'people':'Human Resources', 'customer success':'Customer Success', 'customer service':'Customer Success', 'support':'Customer Success', 'project management':'Project Management', 'strategy':'Strategy', 'legal':'Legal', 'supply chain':'Supply Chain', 'logistics':'Supply Chain', 'procurement':'Supply Chain', 'communications':'Communications', 'public relations':'Communications', 'community':'Community & Social', 'community & social':'Community & Social', 'social':'Community & Social', 'compliance':'Compliance & GRC', 'compliance & grc':'Compliance & GRC', 'grc':'Compliance & GRC', 'risk':'Compliance & GRC' };
// A map target the register does not carry is a build defect: fail here, never mint a choice.
for(const v of Object.values(SEN)){ if(!SENIORITY.has(v)) throw new Error('Build People: Seniority "'+v+'" is not on the register'); }
for(const v of Object.values(DEP)){ if(!DEPARTMENT.has(v)) throw new Error('Build People: Department "'+v+'" is not on the register'); }
const mapSen=(v)=>SEN[String(v||'').trim().toLowerCase()]||'Unclassified';
const mapDep=(v)=>{ for(const part of String(v||'').split(/[,;|]/)){ const m=DEP[part.trim().toLowerCase()]; if(m) return m; } return ''; };
const seenKey=new Set(); const seenLi=new Set();
const stats={ built:0, heldSkipped:0, dupes:0, noKey:0 };
const out=[];
for(const c of plan.plan){
  const heldKeys=new Set(c.heldKeys||[]); const heldLi=new Set((c.heldLinkedin||[]).map(l=>l.toLowerCase()));
  for(const list of tiers){
    for(const p of (list[c.domain]||[])){
      const full=String(p.name||'').trim();
      const first=cleanFirst(full), last=cleanLast(full);
      const key=(first.toLowerCase()+last.toLowerCase()+c.domain).trim();
      const li=String(p.linkedin||'').trim(); const lil=li.toLowerCase();
      if(!key||!first){ stats.noKey++; continue; }
      if(heldKeys.has(key)||(lil&&heldLi.has(lil))){ stats.heldSkipped++; continue; }
      if(seenKey.has(key)||(lil&&seenLi.has(lil))){ stats.dupes++; continue; }
      seenKey.add(key); if(lil) seenLi.add(lil);
      const row={
        'Name': full,
        'Title': String(p.title||''),
        'Seniority': mapSen(p.seniority),
        'Department': mapDep(p.department),
        'Email': String(p.email||'').trim(),
        'LinkedIn URL': li,
        'Phone': String(p.phone||''),
        'Companies': [c.recordId],
        'Contact Key': key,
        'Contact Source': p.source,
        'Source ID': String(p.sourceId||''),
        '_domain': c.domain
      };
      if(!row['Department']) delete row['Department'];
      for(const k of Object.keys(row)){ if(k.charAt(0)==='_') continue; if(!have.has(k)) delete row[k]; }
      out.push({ json: row }); stats.built++;
    }
  }
}
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Apply DNC: one pass for both modes (the writer's ContaGen and Supersoniq rows, the ark pass's
// AI-Ark rows; Any People? feeds Clean Fields from either builder). Drops people whose domain sits
// on the client's DNC table (every page of it, read once by Get DNC Domains); the domain is the
// _domain carrier the builders set, backed by a Contact Key -> domain map read straight from the
// builders in case the helper dropped the carrier. Then fences the write set to exactly what this
// machine writes on People (ruled 2026-09-02): Name, Title, Seniority, Department, Email,
// LinkedIn URL, Phone, Companies, Contact Key, Contact Source, Source ID, plus first_name and
// last_name, the split Clean Fields made from Name (register text fields the linkedin_name_match
// formula reads). Domain, Company and Tag are lookups through the Companies link and are never
// written; every other key, carriers included, is stripped, and a key the table does not carry is
// stripped too, so the writer never meets an unknown field. Zero survivors still emit one {_empty}
// placeholder so the gate reaches the close. Batch Summary counts the drop as rows in minus rows out.
const WRITE_FIELDS=['Name','first_name','last_name','Title','Seniority','Department','Email','LinkedIn URL','Phone','Companies','Contact Key','Contact Source','Source ID'];
const have=new Set(($('Batch Input').first().json.peopleFields)||[]);
const allow=new Set(WRITE_FIELDS.filter(k=>have.has(k)));
const dnc=new Set();
try{ for(const it of $('Get DNC Domains').all()){ const j=it.json||{}; const f=j.fields||{}; const d=String(f.Domain||f.domain||'').toLowerCase().trim(); if(d) dnc.add(d); } }catch(e){}
const domainByKey={};
const learn=(n)=>{ try{ for(const it of $(n).all()){ const j=it.json||{}; const k=String(j['Contact Key']||'').toLowerCase(); if(k&&j._domain) domainByKey[k]=String(j._domain).toLowerCase(); } }catch(e){} };
learn('Build People'); learn('Build Ark People');
const out=[];
for(const i of $('Clean Fields').all()){
  const j=i.json||{};
  if(j._empty) continue;
  const key=String(j['Contact Key']||'').toLowerCase().trim();
  if(!key) continue;
  const d=String(j._domain||domainByKey[key]||'').toLowerCase().trim();
  if(dnc.size&&d&&dnc.has(d)) continue;
  const row={};
  for(const k of Object.keys(j)){ if(allow.has(k)) row[k]=j[k]; }
  out.push({ json: row });
}
if(!out.length) return [{ json: { _empty:true } }];
return out;

// Chunk People: the survivors of Apply DNC in tens, one item per Airtable request. Write People
// PATCHes each as {performUpsert: {fieldsToMergeOn: ["Contact Key"]}, records, typecast} at 200 ms
// apart: the Airtable node sends one record per request (measured 4.5 rows per second, 2026-09-02);
// this writer sends ten per request at five requests per second, 50 rows per second. The Contact
// Keys and the size ride on the item, never in the body, for the count-back: written rows are
// counted from the answer's records[], a failed request counts every record in it as a write error.
const rows=$input.all().map(i=>i.json).filter(j=>j&&!j._empty&&j['Contact Key']);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json: {
    body: { performUpsert: { fieldsToMergeOn: ['Contact Key'] }, records: part.map(r=>({ fields: r })), typecast: true },
    keys: part.map(r=>String(r['Contact Key']).toLowerCase()),
    size: part.length
  } });
}
return out;

// Stamp Rows: Contacts Pulled At = now on every company in the batch, tried or not, found or
// not, in tens, one item per Airtable request (Stamp Companies PATCHes each by record id, typecast
// on, 200 ms apart). The Not Sourced view drops them; Not Covered keeps the zero-contact ones
// visible. Writer mode only: the ark pass stamps nothing new.
const plan=$('Plan Batch').first().json;
const now=new Date().toISOString();
const ids=plan.plan.map(c=>c.recordId).filter(Boolean);
const out=[];
for(let i=0;i<ids.length;i+=10){
  const part=ids.slice(i,i+10);
  out.push({ json: { body: { records: part.map(id=>({ id: id, fields: { 'Contacts Pulled At': now } })), typecast: true }, size: part.length } });
}
return out;

// Recount Filters: after the writer's stamps, read People again for the batch's domains, ids
// only (Contact Key, LinkedIn URL, Domain), one OR formula per 100 domains: the batch's coverage
// is what the base holds now, and the same held state goes back to the parent, which hands it to
// this batch's AI-Ark pass so AI-Ark is sized to the gap and its exclude list is exact. Domain on
// People is a lookup through the Companies link; filterByFormula {Domain}='x' matches the lookup's
// text, so the read works unchanged.
const plan=$('Plan Batch').first().json;
const d=plan.plan.map(c=>c.domain);
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){
  const chunk=d.slice(i,i+100);
  out.push({ json: { formula: chunk.length===1?("{Domain}='"+esc(chunk[0])+"'"):('OR('+chunk.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')') } });
}
if(!out.length) out.push({ json: { formula: "{Domain}=''" } });
return out;

// Ark Plan: tier 3 is absolute, sized to the gap the base still showed when the writer batch that
// covered each company closed: the parent's Ark Lane passes that batch's recount as held state on
// every company (heldCount, heldKeys, heldLinkedin, carried into the plan by Plan Batch), so no
// read happens here. One lane per run since 2026-09-02, never one pass per batch. Only
// companies under their band cap, size = cap minus held, the LinkedIn URLs held at that domain
// excluded (contact.linkedin.any.exclude, verified in their docs 2026-09-02). One export per
// company. Export People with Email: 0.5 credits per person plus 0.5 per email found. Completion
// comes through the callback door: the export's webhook is AI-Ark Export Callback's door with the
// parent execution id as ?run=, and that door records every call into the data table Read
// Callbacks polls.
const inp=$('Batch Input').first().json;
const plan=$('Plan Batch').first().json;
// Seniority enum verified in docs 2026-09-02 (people-export-with-email): founder, owner, partner,
// c_suite, vp, director, head, manager, senior, mid-level, entry, intern. The contract's "cxo" is c_suite.
// Three settings, in this order of precedence (ruled 2026-09-02):
//   1. the launch row's Roles, mapped into AI-Ark's vocabulary by the parent's Launch Params;
//   2. the AI-Ark-only mode (Tiers = "AI-Ark"), the intent path: the real buyers only, since that
//      lane carries the whole run on a flat cap of five people per company;
//   3. the full waterfall's wider net, where AI-Ark is the third tier over what the first two left.
const SENIORITY=['founder','owner','partner','c_suite','vp','head','director','manager'];
const ARK_ONLY_SENIORITY=['founder','owner','partner','c_suite','vp'];
// The export endpoint requires an HTTPS webhook (verified in docs). The door is AI-Ark Export
// Callback (POST /webhook/ai-ark-export-noop), which answers 200 at once and records the call.
const WEBHOOK='https://n8n.flowroots.com/webhook/ai-ark-export-noop?run='+encodeURIComponent(String(inp.parentExecId||''));
const functions=Array.isArray(plan.arkFunctions)?plan.arkFunctions:[];
const roleSeniority=Array.isArray(plan.arkSeniority)?plan.arkSeniority:[];
const seniority=roleSeniority.length?roleSeniority:(plan.arkOnly?ARK_ONLY_SENIORITY:SENIORITY);
const requests=[]; const heldOut={};
if(plan.arkOn){
  for(const c of plan.plan){
    const h={ count:Number(c.held)||0, keys:Array.isArray(c.heldKeys)?c.heldKeys:[], linkedin:Array.isArray(c.heldLinkedin)?c.heldLinkedin:[] };
    heldOut[c.domain]=h;
    const gap=c.cap-h.count; if(gap<=0) continue;
    const exclude=Array.from(new Set(h.linkedin.filter(u=>/linkedin\.com\/in\//i.test(u))));
    const contact={ seniority:{ any:{ include:seniority } } };
    if(exclude.length) contact.linkedin={ any:{ exclude:exclude } };
    // contact.departmentAndFunction.any.include (key and nesting verified in docs); values come from
    // the parent's mapping of the launch row's Departments into AI-Ark's taxonomy, never guessed here.
    if(functions.length) contact.departmentAndFunction={ any:{ include:functions } };
    requests.push({ domain:c.domain, gap:gap, body:{ account:{ domain:{ any:{ include:[c.domain] } } }, contact:contact, page:0, size:gap, webhook:WEBHOOK } });
  }
}
return [{ json: { arkRequests:requests, held:heldOut, arkSeniorityUsed:seniority } }];

// Ark Requests: one item per AI-Ark export, one per company still under its cap. Since 2026-09-02
// this pass is the run's only AI-Ark traffic (one lane, never one per batch), so the whole global
// ceiling belongs to it: Ark Export paces 250 ms apart, four per second against a documented five
// per second and 300 per minute. Ark Windows hands them over fifty at a time so Ark Window Check
// can stop the submission when AI-Ark starts refusing instead of burning every remaining company.
return ($('Ark Plan').first().json.arkRequests||[]).map((r,i)=>({ json: { i: i, domain: r.domain, gap: r.gap, body: r.body } }));

// Ark Track: every window's export answers (Ark Export run by run, paired to Ark Window's items)
// -> one poll state: pending track ids, exports already DONE at submission, submit errors, the
// attempt counter, and submittedAt, the clock the 4-minute safety net runs on (this node runs the
// moment the last window landed). toPoll holds the exports whose statistics one read will settle
// later. Since 2026-09-02 the lane submits in windows of fifty behind Ark Window Check's circuit
// breaker, so this also carries what the breaker did: how many answers were 429, whether it
// stopped, and how many planned companies were therefore never submitted (unserved). Response
// shape verified in docs 2026-09-02: { trackId, state (PENDING | DONE), statistics
// { total, found }, webhook { state, retry }, description }.
const runs=(name)=>{ const out=[]; for(let i=0;i<10000;i++){ let it=null; try{ it=$(name).all(0,i); }catch(e){ break; } if(!it||!it.length) break; out.push(it); } return out; };
let planned=0; try{ planned=$('Ark Requests').all().length; }catch(e){}
let stoppedEarly=false;
try{ const cr=runs('Ark Window Check'); const last=cr[cr.length-1]; stoppedEarly=!!(last&&last[0]&&last[0].json&&last[0].json.stop); }catch(e){}
const reqRuns=runs('Ark Window'), respRuns=runs('Ark Export');
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const why=(b,raw)=>{ const m=b&&typeof b==='object'?(b.detail||b.error||b.message||b.description):null; const s=m?String(typeof m==='object'?JSON.stringify(m):m):(typeof raw==='string'?raw:(raw?JSON.stringify(raw):'')); return String(s||'empty body').slice(0,200); };
const st={ pending:[], done:[], toPoll:[], errors:[], submitted:0, planned:planned, rateLimited:0, unserved:0, stoppedEarly:stoppedEarly, submittedAt:Date.now(), attempts:0, callbacks:0 };
for(let r=0;r<respRuns.length;r++){
  const reqs=reqRuns[r]||[]; const resps=respRuns[r]||[];
  for(let i=0;i<resps.length;i++){
    const req=(reqs[i]||{}).json; if(!req) continue;
    st.submitted++;
    const j=(resps[i]||{}).json||{};
    if(j.error&&j.statusCode===undefined){ st.errors.push({ domain:req.domain, reason:'AI-Ark export: '+String((j.error&&j.error.message)||'call failed').slice(0,160) }); continue; }
    const status=Number(j.statusCode)||0; const b=parse(j.body===undefined?j:j.body);
    const trackId=b&&typeof b==='object'?String(b.trackId||''):'';
    if(status===429) st.rateLimited++;
    if(!(status>=200&&status<300)||!trackId){ st.errors.push({ domain:req.domain, reason:'AI-Ark export HTTP '+status+' '+why(b,j.body) }); continue; }
    const entry={ domain:req.domain, trackId:trackId, gap:req.gap };
    if(String(b.state||'').toUpperCase()==='DONE') st.done.push(Object.assign(entry,{ total:Number((b.statistics||{}).total)||0, found:Number((b.statistics||{}).found)||0 }));
    else st.pending.push(entry);
  }
}
st.unserved=Math.max(0, planned-st.submitted);
return [{ json: st }];

// Ark Pending: one item per track id still pending. The whole poll state rides on the FIRST item
// only, which is all Ark Check reads: the lane can hold thousands of pending exports at once, and
// a copy of the state on every item is quadratic memory (the n8n host has been OOM-killed by
// exactly that shape before). Read Callbacks queries the data table once per item, by track id.
const st=$input.first().json||{};
return (st.pending||[]).map((p,i)=>{
  const o={ trackId:p.trackId, domain:p.domain, gap:p.gap };
  if(i===0) o.state=st;
  return { json: o };
});

// Ark Check: the callback rows (Read Callbacks, one data table query per pending track id; AI-Ark
// Export Callback fills that table from every completion webhook) -> the next poll state. A row
// in state DONE settles the export: found from the row when the webhook carried statistics, else
// into toPoll for one statistics read later; no row keeps it pending. Polled every 15 s, clocked
// from submittedAt. The 4-minute cap is the safety net for exports whose webhook never arrives:
// past it, whatever is still pending moves to toPoll, where one statistics read each decides DONE
// or still PENDING. Never a hang, never a poll per export while the webhook works. The breaker's
// counters (planned, rateLimited, unserved, stoppedEarly) ride through untouched.
const WAIT_MS=15000, MAX_POLL_MS=240000;
let pend=[]; try{ pend=$('Ark Pending').all().map(i=>i.json); }catch(e){}
const prev=(pend[0]&&pend[0].state)||{ pending:[], done:[], toPoll:[], errors:[], submitted:0, planned:0, rateLimited:0, unserved:0, stoppedEarly:false, attempts:0 };
const now=Date.now(); const submittedAt=Number(prev.submittedAt)||now; const elapsed=now-submittedAt;
const rows={};
try{ for(const it of $('Read Callbacks').all()){ const j=it.json||{}; const id=String(j.trackId||'').trim(); if(id) rows[id]=j; } }catch(e){}
const st={ pending:[], done:(prev.done||[]).slice(), toPoll:(prev.toPoll||[]).slice(), errors:(prev.errors||[]).slice(), submitted:prev.submitted||0, planned:prev.planned||0, rateLimited:prev.rateLimited||0, unserved:prev.unserved||0, stoppedEarly:!!prev.stoppedEarly, submittedAt:submittedAt, attempts:(prev.attempts||0)+1, callbacks:(prev.callbacks||0)+Object.keys(rows).length };
const known=(v)=>v!==null&&v!==undefined&&v!==''&&isFinite(Number(v))&&Number(v)>=0;
for(const p of pend){
  const entry={ domain:p.domain, trackId:p.trackId, gap:Number(p.gap)||0 };
  const r=rows[p.trackId];
  const state=r?String(r.state||'').toUpperCase():'';
  if(state==='DONE'){
    if(known(r.found)) st.done.push(Object.assign(entry,{ total:known(r.total)?Number(r.total):0, found:Number(r.found) }));
    else st.toPoll.push(Object.assign(entry,{ why:'webhook DONE without statistics' }));
    continue;
  }
  if(state&&state!=='PENDING'&&state!=='IN_PROGRESS'&&state!=='PROCESSING'&&state!=='RUNNING'){ st.errors.push({ domain:p.domain, reason:'AI-Ark export '+p.trackId+' reported state '+state }); continue; }
  st.pending.push(entry);
}
if(st.pending.length&&elapsed+WAIT_MS>=MAX_POLL_MS){
  const secs=Math.round(elapsed/1000);
  for(const p of st.pending) st.toPoll.push(Object.assign({}, p, { why:'no webhook after '+secs+' s' }));
  st.pending=[];
}
return [{ json: st }];

// Fill Found: one item per export whose statistics are still unknown (a DONE webhook without
// statistics.found, or no webhook inside the 4-minute cap); Ark Statistics reads each once, 250 ms
// apart, and Ark Found settles them. The whole state rides on the FIRST item only, which is all
// Ark Found reads: the list can be thousands long on a lane, and a copy per item is quadratic
// memory. Nothing to poll: one placeholder (empty trackId) so Any To Poll? routes straight to Ark
// Found. The input is the state item from Ark Track (nothing was pending), Ark Check (the poll
// drained) or Ark Plan (no export at all; an empty state is built).
const inp=$input.first().json||{};
const st=Array.isArray(inp.pending)?inp:{ pending:[], done:[], toPoll:[], errors:[], submitted:0, planned:0, rateLimited:0, unserved:0, stoppedEarly:false, submittedAt:Date.now(), attempts:0, callbacks:0 };
const list=Array.isArray(st.toPoll)?st.toPoll:[];
if(!list.length) return [{ json: { trackId:'', state:st } }];
return list.map((p,i)=>{
  const o={ trackId:p.trackId, domain:p.domain, gap:Number(p.gap)||0, why:p.why||'' };
  if(i===0) o.state=st;
  return { json: o };
});

// Ark Found: the final export state. The polled statistics (Ark Statistics answers, aligned to
// Fill Found's items) settle the unknowns: DONE with statistics -> done; still PENDING -> an
// error (the webhook never came and the cap passed); a 4xx -> an error (403 stuck refund, 404
// expired). Everything else is what the callbacks already settled, and the breaker's counters
// (planned, rateLimited, unserved, stoppedEarly) ride through to the log. Ark Result Items reads
// done from here and fetches only where found > 0.
let polled=[]; let st=null;
try{ const all=$('Fill Found').all().map(i=>i.json); st=(all[0]&&all[0].state)||null; polled=all.filter(x=>x.trackId); }catch(e){}
st=st||{ pending:[], done:[], toPoll:[], errors:[], submitted:0, planned:0, rateLimited:0, unserved:0, stoppedEarly:false, attempts:0, callbacks:0 };
const out={ pending:[], done:(st.done||[]).slice(), toPoll:[], errors:(st.errors||[]).slice(), submitted:st.submitted||0, planned:st.planned||0, rateLimited:st.rateLimited||0, unserved:st.unserved||0, stoppedEarly:!!st.stoppedEarly, submittedAt:st.submittedAt, attempts:st.attempts||0, callbacks:st.callbacks||0, polled:polled.length };
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const resp=polled.length?$input.all():[];
polled.forEach((p,i)=>{
  const j=(resp[i]&&resp[i].json)||{};
  const status=Number(j.statusCode)||0; const b=parse(j.body===undefined?j:j.body);
  const state=b&&typeof b==='object'?String(b.state||'').toUpperCase():'';
  const entry={ domain:p.domain, trackId:p.trackId, gap:Number(p.gap)||0 };
  if(status>=200&&status<300&&state==='DONE'){ out.done.push(Object.assign(entry,{ total:Number((b.statistics||{}).total)||0, found:Number((b.statistics||{}).found)||0 })); return; }
  if(status>=200&&status<300){ out.errors.push({ domain:p.domain, reason:'AI-Ark export '+p.trackId+' still '+(state||'unknown')+' ('+p.why+')' }); return; }
  out.errors.push({ domain:p.domain, reason:'AI-Ark statistics HTTP '+status+' for '+p.trackId+' ('+p.why+') '+String((b&&(b.description||b.message||b.error))||(j.error&&j.error.message)||'').slice(0,120) });
});
return [{ json: out }];

// Ark Result Items: one item per finished export that found anyone (found > 0; 78 percent of
// exports return nothing, measured 2026-09-02, and the results door is not read for those). The
// results door is paged by the HTTP node. Nothing to fetch: one placeholder (empty trackId) so
// Any Ark Results? routes straight to Parse Ark.
const st=$input.first().json||{};
const items=(st.done||[]).filter(d=>Number(d.found)>0).map(d=>({ json: { trackId:d.trackId, domain:d.domain, gap:d.gap, total:d.total, found:d.found } }));
return items.length?items:[{ json: { trackId:'' } }];

// Parse Ark: export result pages (bodies carrying trackId and content[]) -> people per domain,
// kept up to the gap. Results endpoint verified in docs 2026-09-02: GET
// /v1/people/export/{trackId}/inquiries?page&size, content[] of { id, profile { full_name,
// title, headline }, department { seniority, functions }, link { linkedin }, location, email
// { state, output [ { address, status } ] } }. Email: the first VALID address delivered, else
// the first address; emails land as delivered. Credits: 0.5 per person plus 0.5 per email
// found, from the statistics each export reported (the results door carries no credit figure).
// The state comes from Ark Found (every export settled: callbacks, then the one-shot polls).
let st={ pending:[], done:[], errors:[], submitted:0, planned:0, rateLimited:0, unserved:0, stoppedEarly:false, attempts:0, callbacks:0, polled:0 };
try{ st=$('Ark Found').first().json||st; }catch(e){}
let items=[]; try{ items=$('Ark Results').all(); }catch(e){}
const doneByTrack={}; for(const d of (st.done||[])) doneByTrack[d.trackId]=d;
const people={};
const stats={ called:Number(st.submitted)||0, returned:0, kept:0, credits:0, errors:(st.errors||[]).length, firstError:((st.errors||[])[0]||{}).reason||'', failReasons:(st.errors||[]).slice(0,5).map(e=>'AI-Ark '+e.domain+': '+e.reason), polls:Number(st.attempts)||0, callbacks:Number(st.callbacks)||0, polled:Number(st.polled)||0, done:(st.done||[]).length, withPeople:(st.done||[]).filter(d=>Number(d.found)>0).length, planned:Number(st.planned)||0, rateLimited:Number(st.rateLimited)||0, unserved:Number(st.unserved)||0, stoppedEarly:!!st.stoppedEarly };
